import{_ as e,o,c as d,a2 as r}from"./chunks/framework.BEUshCVJ.js";const p=JSON.parse('{"title":"快捷键","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/shortcuts.md","filePath":"zh/guide/shortcuts.md","lastUpdated":1793129281000}'),a={name:"zh/guide/shortcuts.md"};function l(c,t,i,h,s,n){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="快捷键" tabindex="-1">快捷键 <a class="header-anchor" href="#快捷键" aria-label="Permalink to &quot;快捷键&quot;">​</a></h1><p>本页列出 MeetCue 的全局快捷键并说明如何修改。焦点在会议软件上时这些快捷键同样有效。</p><h2 id="默认快捷键" tabindex="-1">默认快捷键 <a class="header-anchor" href="#默认快捷键" aria-label="Permalink to &quot;默认快捷键&quot;">​</a></h2><table tabindex="0"><thead><tr><th>快捷键</th><th>动作</th></tr></thead><tbody><tr><td><code>Ctrl+Alt+Space</code></td><td>开始 / 暂停拾取</td></tr><tr><td><code>Ctrl+Alt+H</code></td><td>面板：完整 → 迷你条 → 隐藏</td></tr><tr><td><code>Ctrl+Alt+[</code></td><td>上一问</td></tr><tr><td><code>Ctrl+Alt+]</code></td><td>下一问（练习中为跳过当前题）</td></tr><tr><td><code>Ctrl+Alt+Enter</code></td><td>把当前问题标为已答</td></tr><tr><td><code>Ctrl+Alt+Shift</code> + 方向键</td><td>把面板向上、下、左、右移动</td></tr><tr><td><code>Ctrl+Alt+Shift+1</code>、<code>2</code>、<code>3</code></td><td>把面板移到保存的位置 1、2 或 3（该位置为空时：保存面板当前位置）</td></tr><tr><td><code>Ctrl+Alt+Shift+P</code></td><td>隐藏面板 6 秒；再按一次立即回来</td></tr><tr><td><code>Ctrl+Alt+Shift+T</code></td><td>开启或关闭鼠标点击穿透面板</td></tr></tbody></table><h2 id="move-the-panel" tabindex="-1">移动面板 <a class="header-anchor" href="#move-the-panel" aria-label="Permalink to &quot;移动面板 {#move-the-panel}&quot;">​</a></h2><p>把面板放在摄像头正下方，看提示时就像在看对方。按一下 <code>Ctrl+Alt+Shift</code> 加方向键，面板移动一小步；按住不放则持续移动。同时按住两个方向键可以斜着移动。面板不会移出屏幕，推过屏幕侧边时会移到相邻的屏幕，并记住你放下的位置。</p><h2 id="saved-spots" tabindex="-1">保存的位置 <a class="header-anchor" href="#saved-spots" aria-label="Permalink to &quot;保存的位置 {#saved-spots}&quot;">​</a></h2><p>大多数会议里面板都有两三个合适的位置：共享屏幕旁边、摄像头下方，或者避开其他参会者视频的角落。每个位置保存一次，之后用快捷键来回切换：</p><ol><li>把面板放到不挡任何东西的地方。可以用面板上的 <strong>移动</strong> 贴靠到边缘或角落，也可以直接拖动。</li><li>按 <code>Ctrl+Alt+Shift+1</code>。该位置为空时，快捷键会保存面板当前的位置、大小和形态（完整面板或迷你条）。</li><li>之后再按 <code>Ctrl+Alt+Shift+1</code>，面板就会回到这里。</li></ol><p>面板上的 <strong>移动 › 已保存的位置</strong> 和 <strong>设置 › 通用 › 面板</strong> 会列出这些位置，并可以改存或删除。</p><h2 id="操作面板后面的内容" tabindex="-1">操作面板后面的内容 <a class="header-anchor" href="#操作面板后面的内容" aria-label="Permalink to &quot;操作面板后面的内容&quot;">​</a></h2><ul><li><code>Ctrl+Alt+Shift+P</code> 把面板隐藏 6 秒，足够点击面板后面的 <strong>加入会议</strong> 或其他会议按钮，之后自动回来。</li><li><code>Ctrl+Alt+Shift+T</code> 开启鼠标点击穿透：面板变淡，鼠标直接作用于后面的窗口。再按一次快捷键，或在托盘菜单中点 <strong>鼠标点击穿透面板</strong>，面板即可恢复点击。</li></ul><h2 id="为什么选这些键" tabindex="-1">为什么选这些键 <a class="header-anchor" href="#为什么选这些键" aria-label="Permalink to &quot;为什么选这些键&quot;">​</a></h2><p>默认键位避开了 Windows 笔记本上常见的快捷键：</p><ul><li>会议软件常用的 <code>Ctrl+Shift</code> 组合，例如 Teams 的静音；</li><li>输入法使用的 <code>Ctrl+Space</code> 或 <code>Shift+Space</code>；</li><li>显卡驱动用于旋转屏幕的 <code>Ctrl+Alt</code> 加方向键，所以移动面板的快捷键另加了 <code>Shift</code>；</li><li>聊天软件使用的 <code>Ctrl+Alt+A</code>、<code>Ctrl+Alt+W</code>、<code>Ctrl+Alt+Z</code>；</li><li>功能键，很多笔记本默认把它们当作媒体键。</li></ul><h2 id="修改快捷键" tabindex="-1">修改快捷键 <a class="header-anchor" href="#修改快捷键" aria-label="Permalink to &quot;修改快捷键&quot;">​</a></h2><ol><li>打开 <strong>设置 › 快捷键</strong>。</li><li>点击对应动作旁的 <strong>修改</strong>。</li><li>按下新的组合键。按 <code>Esc</code> 取消。</li></ol><p>如果该组合已被其他程序占用，这一行会标红并显示 <a href="/meetcue/zh/troubleshooting/error-codes#mc-hk-001">MC-HK-001</a>，请换一个组合。<strong>恢复默认</strong> 会还原上表的键位。</p><h2 id="快捷键收不到的情况" tabindex="-1">快捷键收不到的情况 <a class="header-anchor" href="#快捷键收不到的情况" aria-label="Permalink to &quot;快捷键收不到的情况&quot;">​</a></h2><p>前台窗口是以管理员身份运行的程序，或独占全屏的游戏时，Windows 不会把快捷键传给 MeetCue。参见<a href="/meetcue/zh/troubleshooting/panel">快捷键与悬浮窗</a>。</p>',20)])])}const f=e(a,[["render",l]]);export{p as __pageData,f as default};
